const entrada = $input.first().json;
const datos = entrada.body ?? entrada;
const consulta = String(datos.consulta ?? datos.chatInput ?? '').trim();
if (!consulta || consulta.length > 800) throw new Error('Escribe una consulta de 1 a 800 caracteres.');
const correo_reportes = 'REEMPLAZAR_CORREO_REPORTES';
const correo = String(datos.correo ?? correo_reportes).trim();
if (!/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(correo)) throw new Error('Falta un correo válido para la respuesta.');
return [{ json: { consulta, correo, correo_reportes, origen: entrada.body ? 'Google Forms / Webhook' : 'Chat de prueba', recibido: new Date().toISOString() } }];

const resultado = $input.first().json;
const entrada = $('Preparar consulta').first().json;
const texto = typeof resultado.output === 'string' ? resultado.output.trim() : '';
const fallo = Boolean(resultado.error) || !texto || /agent stopped|max(?:imum)? iterations|iteration limit/i.test(texto);
const output = fallo ? 'No pude verificar la información en este momento. Tu consulta requiere revisión de recepción. Esta es una demostración con datos ficticios.' : texto;
const pasos = Array.isArray(resultado.intermediateSteps) ? resultado.intermediateSteps : [];
const registro = pasos.map((paso, i) => ({
  paso: i + 1,
  herramienta: paso.action?.tool ?? 'No informada',
  entrada: paso.action?.toolInput ?? {},
  observacion: String(typeof paso.observation === 'string' ? paso.observation : JSON.stringify(paso.observation ?? '')).slice(0,5000)
}));
const estado = fallo ? 'requiere_revision' : 'respuesta_generada';
const reporte = [
  'CHECKPOINT 1 — ESTÉTICA AURORA (DATOS FICTICIOS)',
  'Ejecución: ' + $execution.id,
  'Fecha UTC: ' + new Date().toISOString(),
  'Origen: ' + entrada.origen,
  'Estado del agente: ' + estado,
  'Consulta: ' + entrada.consulta,
  'Respuesta: ' + output,
  'Máximo de iteraciones: 5',
  'Llamadas a herramientas registradas: ' + registro.length,
  'Registro de herramientas (sin razonamiento interno):',
  JSON.stringify(registro, null, 2),
  'El registro completo puede revisarse en Executions de n8n.'
].join('\n\n');
return [{ json: { output, estado, reporte, correo: entrada.correo, correo_reportes: entrada.correo_reportes, id_ejecucion: String($execution.id), llamadas_herramientas: registro.length } }];
